from itertools import combinations
G=['.##.##.','######.','.##.#..','..###..']
ones={(r,c) for r,row in enumerate(G) for c,x in enumerate(row) if x=='#'}
shapes=[]
for r in range(3):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=ones: shapes.append(('sq',r,c,sq))
for r in range(3):
 for c in range(6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for miss in box:
   sh=box-{miss}
   if sh<=ones: shapes.append(('L',r,c,sh))
solutions=[]
def rec(remaining,chosen):
 if not remaining:
  solutions.append(chosen);return
 p=min(remaining)
 for typ,r,c,s in shapes:
  if p in s and s<=remaining: rec(remaining-s,chosen+[(typ,r,c,s)])
rec(ones,[])
print('ones',len(ones),'shapes',len(shapes),'solutions',len(solutions))
for sol in solutions[:10]: print([(t,r,c,sorted(s)) for t,r,c,s in sol])
